    {
      "id": "r3",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "प्राणानामाघातस्तस्मात् । संयमः मनसो नियमनम् । युवतीनां जनः युवति-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "जनः । परेषां युवतिजनस्य कथाः तासु मूकभावः । तृष्णायाः स्रोतः प्रवाहः तस्य",
          "end": "space"
        },
        {
          "n": 3,
          "text": "विभङ्गः । न उपहतः अनुपहतः अनुपहतः विधिर्यस्य । स्रग्धरावृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "प्रारभ्यते न खलु विघ्नभयेन नीचैः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "प्रारभ्य विघ्नविहता विरमन्ति मध्याः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "विघ्नैः पुनः[१] पुनरपि प्रतिहन्यमानाः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्रारब्धमुत्तमजना न परित्यजन्ति ॥ २७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "नीचैः क्षुद्रैः । ये विघ्नभयान्न किमप्यारभते ते नीचा इत्यर्थः । स्पष्टमन्यत् ।",
          "end": "space"
        },
        {
          "n": 2,
          "text": "वसन्ततिलका वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "इदानीं सतामनन्यसाधारणं वृत्तमाह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "प्रिया न्याय्या वृत्तिर्मलिनमसुभङ्गे[२]प्यसुकरं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "त्वसन्तो नाभ्यर्थ्याः सुहृदपि न याच्यः कृशधनः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "विपद्युच्चैः स्थेयं पदमनुविधेयं च महतां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "सतां केनोद्दिष्टं विषममसिधाराव्रतमिदम् ॥ २८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "न्यायादनपेता न्याय्या । धर्मपथ्यर्थन्यायादनपेते ( ४. ४. ९२ ) इति",
          "end": "space"
        },
        {
          "n": 2,
          "text": "यत् । वृत्तिर्वर्तनम् । मलिनं पापं कर्म । असूनां भङ्गः असुभङ्गः तस्मिन् ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "प्राणसङ्कटेपि न कुर्युरित्यर्थः । स्थेयं स्थितिः । असेर्धारा इवासिधारायां चक्रम-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "णमिव वा व्रतमसिधाराव्रतम् । तदुक्तम्–यत्रैकशयनस्थापि प्रमदा नोपभुज्यते ।",
          "end": "space"
        },
        {
          "n": 5,
          "text": "असिधाराव्रतं नाम वदन्ति मुनिपुङ्गवाः । उद्दिष्टमुपदिष्टम् । सन्तो निसर्गादेवै-",
          "end": "hyphen"
        },
        {
          "n": 6,
          "text": "वंशीला इत्यर्थः । शिखरिणी वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "अथ मानशौर्यपद्धतिः—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r10",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "क्षुत्क्षामोपि जराकृशोपि शिथिलप्रायो[२]पि कष्टां[३] दशा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "मापन्नोपि विपन्नदीधितिरपि प्राणेषु नश्यत्स्वपि ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मत्तेभेन्द्र[४]विभिन्नकुम्भकवल[५]ग्रासैकबद्धस्पृहः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "किं जीर्णं तृणमत्ति मानमहतामग्रेसरः केसरी ॥ २९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r11",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "क्षुधा क्षामः क्षीणः क्षुत्क्षामः । क्षायो मः इति मत्वम् । जरया कृशः जरा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "कृशोपि । शिथिलप्रायः बाहुल्येन विश्ल्थाङ्गोपि । प्रायो बाहुल्यतुल्ययोः इति",
          "end": "space"
        },
        {
          "n": 3,
          "text": "मेदिनी । कष्टां कठिनामवस्थां प्राप्तोपि । विपन्ना दीधितिः तेजः यस्य । नष्ट-",
          "end": "hyphen"
        }
      ],
      "uncertain": false,
      "note": null
    },
